from dataclasses import dataclass, field
from pathlib import Path
import logging
from .configuration import RmodConfiguration


@dataclass
class RmodConnection:
    ru_config: RmodConfiguration
    alias: str
    log_dir: Path
    log_prefix: str = ""
    is_connected: bool = False
    master_node = True
    master_node_id = None
    second_uart = False
    slave_node_present = False
    slave_node_timeout = None
    snapshot_name = None
    ram_snapshot_path = None
    ram_extra_logs_path = None
    rom_snapshot_path = None
    rom_extra_logs_path = None
    ips_from_rmod = None
    ip_from_smod = None
    slave_bts = None
    logger: logging.Logger = field(default_factory=logging.getLogger)

    def __str__(self):
        return (
            f"RmodConnection:{self.ru_config}"
            f"alias={self.alias}"
            f"\nlog_dir={self.log_dir}"
            f"\nlog_prefix={self.log_prefix}\n"
        )
